  check('lecture : l\'état indique la page et le texte en cours', (await run(`document.querySelector('[data-speech-status]')?.innerText ?? ''`)).includes('Page 1 — texte 1 sur 1'))
  await clickSel('[data-action="speech-pause"]')
  await sleep(150)
