  const setTheme = (v) => run(`(() => { const s = document.querySelector('[data-settings-dialog] [data-field="theme"]'); Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, 'value').set.call(s, ${JSON.stringify(v)}); s.dispatchEvent(new Event('change', { bubbles: true })) })()`)
