  check('QR code et publipostage : le champ du QR code est reconnu (aucun avertissement)', await waitFor(async () => (await run(`document.querySelector('[data-mm-summary]')?.innerText ?? ''`)).startsWith('2 lignes')) && (await nBrand('[data-mm-none]')) === 0 && (await nBrand('[data-mm-unknown]')) === 0)
  await rm(join(exportsDir, 'Sans titre.pdf'), { force: true })
