  const { PDFDocument: QrPdf } = await import('pdf-lib')
  const qrMergedPdf = await QrPdf.load(qrMerged)
  check('QR code et publipostage : 2 pages (une par ligne)', qrMergedPdf.getPageCount() === 2, String(qrMergedPdf.getPageCount()))
  // le contenu de chaque page diffère (le dessin des modules change d'une ligne à l'autre)
  const pageStreams = qrMergedPdf.getPages().map((pg) => { const c = pg.node.Contents(); const arr = c?.asArray ? c.asArray() : [c]; return arr.map((r) => { const st = qrMergedPdf.context.lookup(r); try { return inflateSync(st.contents).toString('latin1') } catch { return Buffer.from(st.contents).toString('latin1') } }).join('') })
  check('QR code et publipostage : le dessin des modules diffère d\'une page à l\'autre', pageStreams[0].length > 100 && pageStreams[0] !== pageStreams[1])
