  check('nuage de mots : la boîte s\'ouvre, « Insérer » est inactif tant que rien n\'est saisi', (await run(`document.querySelector('[data-cloud-dialog]') ? 1 : 0`)) === 1 && (await run(`document.querySelector('[data-action="cloud-insert"]').disabled`)) === true)
  await run(`(() => { const i = document.querySelector('[data-field="cloudText"]'); Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value').set.call(i, ${JSON.stringify('Soleil ; 12\nPluie ; 8\nVent ; 5\nNeige ; 3\nOrage ; 2')}); i.dispatchEvent(new Event('input', { bubbles: true })) })()`)
  await waitFor(async () => !(await run(`document.querySelector('[data-action="cloud-insert"]').disabled`)))
  const cloudInfo = await run(`document.querySelector('[data-cloud-info]')?.innerText ?? '(boîte absente)'`)
  check('nuage de mots : la liste pondérée est reconnue, 5 mots sur 5', cloudInfo.includes('avec poids') && cloudInfo.includes('5 mots affichés sur 5'), `${cloudInfo} | texte : ${await run(`document.querySelector('[data-field="cloudText"]')?.value.length`)} car.`)
  check('nuage de mots : l\'aperçu est dessiné (des pixels de couleur sur le fond de la page)', (await run(`(() => { const c = document.querySelector('[data-cloud-preview]'); const d = c.getContext('2d').getImageData(0, 0, c.width, c.height).data; let n = 0; for (let i = 0; i < d.length; i += 4) if (d[i] < 200 || d[i + 1] < 200 || d[i + 2] < 200) n++; return n })()`)) > 300)
  await sleep(300)
  const cloudBox = await run(`(() => { const m = document.querySelector('.cloud-dialog'); const t = document.querySelector('[data-field="cloudText"]'); return { textH: Math.round(t.getBoundingClientRect().height), scroll: m.scrollHeight - m.clientHeight, boxH: Math.round(m.getBoundingClientRect().height), win: innerHeight } })()`)
  check('nuage de mots : le champ de texte fait au moins 80 px de haut et la boîte tient sans défiler', cloudBox.textH >= 80 && cloudBox.scroll <= 1, JSON.stringify(cloudBox))
  if (process.env.SMOKE_CLOUD_SHOT) await writeFile(process.env.SMOKE_CLOUD_SHOT, Buffer.from((await cdp('Page.captureScreenshot', { format: 'png' })).result.data, 'base64'))
  await clickSel('[data-action="cloud-insert"]')
  await sleep(600)
