  const voiceVideo = JSON.stringify((await readFile(videoFile)).toString('base64'))
  const voiceMeta = await run(`(async () => { const bin = atob(${voiceVideo}); const a = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) a[i] = bin.charCodeAt(i); const ctx = new OfflineAudioContext(2, 1, 48000); const b = await ctx.decodeAudioData(a.slice().buffer); const ch = b.getChannelData(0); const rms = (from, to) => { let s = 0; const i0 = Math.round(from * b.sampleRate), i1 = Math.min(ch.length, Math.round(to * b.sampleRate)); for (let i = i0; i < i1; i++) s += ch[i] * ch[i]; return Math.sqrt(s / Math.max(1, i1 - i0)) }; return { d: b.duration, voice: rms(0.4, 2.4), after: rms(b.duration - 0.7, b.duration) } })().catch(e => ({ error: String(e) }))`)
  check('voix off : la voix est dans la bande son (et le reste de la vidéo est silencieux)', voiceMeta.voice > 0.003 && voiceMeta.after < 0.001 && voiceMeta.d > videoPages + 1, JSON.stringify(voiceMeta))
  // musique + voix : la musique baisse sous la voix (case cochée), reste à plein volume sinon ; mesure juste avant la voix, quand la baisse est en cours
