  check('chronométrage : l\'écran de l\'orateur s\'ouvre', await waitSpeaker(true))
  const spt = await attachSpeaker()
  check('chronométrage : le temps prévu total est affiché (Prévu 1:00, dans les temps)', await waitFor(async () => /^Prévu 1:00 · dans les temps$/.test((await spText(spt, 'plan')) ?? ''), 8000), String(await spText(spt, 'plan')))
  check('chronométrage : le temps de la page est comparé au temps prévu (Page 0:0x / 1:00)', /^Page 0:\d\d \/ 1:00$/.test((await spText(spt, 'page-time')) ?? ''), String(await spText(spt, 'page-time')))
  await sleep(21000)
