  check('chronométrage : une ligne par page, 1:00 prévu pour la première, plus de 20 s en tout', (await nBrand('[data-timing-row]')) === 3 && (await run(`document.querySelector('[data-timing-row="1"] [data-timing="planned"]')?.innerText`)) === '1:00' && Number(await run(`document.querySelector('[data-timing-total]')?.dataset.timingSpent`)) >= 20)
  await clickSel('[data-action="timing-apply"]')
